gcV(){return"\u0423\u0432\u0435\u043b\u0438\u0447\u0438 \u0434\u043e\u0445\u043e\u0434\u0438\u0442\u0435 \u0441\u0438 \u043a\u0430\u0442\u043e \u043f\u0440\u043e\u0444\u0435\u0441\u0438\u043e\u043d\u0430\u043b\u0438\u0441\u0442, \u0438\u0437\u043f\u043e\u043b\u0437\u0432\u0430\u0439\u043a\u0438 \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430\u0442\u0430 Edhomy \u0437\u0430 \u043c\u0430\u0440\u043a\u0435\u0442\u0438\u043d\u0433, \u043f\u0440\u0438\u0432\u043b\u0438\u0447\u0430\u043d\u0435 \u043d\u0430 \u043a\u043b\u0438\u0435\u043d\u0442\u0438 \u0438 \u043c\u043e\u043d\u0435\u0442\u0438\u0437\u0430\u0446\u0438\u044f \u043d\u0430 \u043e\u0444\u0435\u0440\u0442\u0438\u0442\u0435 \u0441\u0438."},
gez(){return"\u0410\u043a\u043e \u0438\u043c\u0430\u0448 \u0432\u044a\u043f\u0440\u043e\u0441\u0438 \u0437\u0430 \u043d\u0430\u0448\u0430\u0442\u0430 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f, \u043c\u043e\u0436\u0435\u0448 \u0434\u0430 \u043d\u0438 \u043f\u0438\u0448\u0435\u0448 \u0447\u0440\u0435\u0437 \u0441\u043b\u0435\u0434\u043d\u0430\u0442\u0430 \u0444\u043e\u0440\u043c\u0430."},
