geK(){return"\u0421\u044a\u043e\u0431\u0449\u0435\u043d\u0438\u0435\u0442\u043e \u0431\u0435\u0448\u0435 \u0438\u0437\u043f\u0440\u0430\u0442\u0435\u043d\u043e \u0443\u0441\u043f\u0435\u0448\u043d\u043e"},
gbe(a){return"\u0413\u0440\u0435\u0448\u043a\u0430. \u041c\u043e\u043b\u044f, \u043e\u043f\u0438\u0442\u0430\u0439\u0442\u0435 \u043e\u0442\u043d\u043e\u0432\u043e"},
ge6(){return"\u041f\u043e\u043f\u044a\u043b\u043d\u0435\u0442\u0435 \u0432\u0441\u0438\u0447\u043a\u0438 \u043f\u043e\u043b\u0435\u0442\u0430 \u043f\u0440\u0435\u0434\u0438 \u0438\u0437\u043f\u0440\u0430\u0449\u0430\u043d\u0435"},
ge1(){return"\u0410\u043a\u043e \u0441\u0438 \u0441\u043b\u0443\u0436\u0438\u0442\u0435\u043b \u043d\u0430 Edhomy, \u043c\u043e\u043b\u044f \u0432\u043b\u0435\u0437, \u0437\u0430 \u0434\u0430 \u043f\u043e\u043b\u0443\u0447\u0438\u0448 \u0434\u043e\u0441\u0442\u044a\u043f"},
geL(){return"\u041f\u043e\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b \u0438 \u043f\u0430\u0440\u043e\u043b\u0430"},
geO(){return"\u041d\u0430\u043f\u0438\u0448\u0438 \u043f\u043e\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b\u0441\u043a\u043e\u0442\u043e \u0438\u043c\u0435 \u0442\u0443\u043a"},
gei(){return"\u041d\u0430\u043f\u0438\u0448\u0438 \u043f\u0430\u0440\u043e\u043b\u0430\u0442\u0430 \u0442\u0443\u043a"},
gdm(a){return"\u041f\u043e\u0442\u0432\u044a\u0440\u0434\u0438"},
geI(){return"\u041f\u0430\u0440\u043e\u043b\u0430\u0442\u0430 \u0438\u043b\u0438 \u043f\u043e\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b\u044f\u0442 \u0441\u0430 \u043d\u0435\u0432\u0430\u043b\u0438\u0434\u043d\u0438. \u041c\u043e\u043b\u044f, \u0441\u0432\u044a\u0440\u0436\u0438 \u0441\u0435 \u0441 \u0442\u0432\u043e\u044f \u0440\u044a\u043a\u043e\u0432\u043e\u0434\u0438\u0442\u0435\u043b"},
gev(){return"\u041c\u043e\u043b\u044f, \u0432\u044a\u0432\u0435\u0434\u0438 \u043f\u0440\u0430\u0432\u0438\u043b\u043d\u043e \u043f\u043e\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b \u0438 \u043f\u0430\u0440\u043e\u043b\u0430"},
gcz(){return"\u0418\u0437\u0445\u043e\u0434"},
ge0(){return"\u0421\u043e\u0444\u0442\u0443\u0435\u0440"},
